-- Guarded cleanup of inert legacy resource child pools, batch 11.
-- Physical gameobject rows are untouched.
START TRANSACTION;
DELETE pp FROM pool_pool pp LEFT JOIN pool_creature pc ON pc.pool_entry=pp.pool_id LEFT JOIN pool_gameobject pg ON pg.pool_entry=pp.pool_id LEFT JOIN pool_quest pq ON pq.pool_entry=pp.pool_id LEFT JOIN game_event_pool gep ON gep.pool_entry=pp.pool_id LEFT JOIN pool_pool child ON child.mother_pool=pp.pool_id WHERE pp.pool_id IN (2478,2479,2480,2481,2482,2483,2484,2486,2488,2489,2490,2491,2492,2493,2494,2495,2496,2497,2498,2500,2502,2503,2504,2506,2507,2508,2509,2511,2512,2513,2514,2515,2517,2518,2523,2529,2532,2564,2566,2568,2574,2578,2585,2593,2597,2630,2638,2642,2649,2658) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND child.pool_id IS NULL;
DELETE pt FROM pool_template pt LEFT JOIN pool_creature pc ON pc.pool_entry=pt.entry LEFT JOIN pool_gameobject pg ON pg.pool_entry=pt.entry LEFT JOIN pool_quest pq ON pq.pool_entry=pt.entry LEFT JOIN game_event_pool gep ON gep.pool_entry=pt.entry LEFT JOIN pool_pool pp_child ON pp_child.pool_id=pt.entry LEFT JOIN pool_pool pp_mother ON pp_mother.mother_pool=pt.entry WHERE pt.entry IN (2478,2479,2480,2481,2482,2483,2484,2486,2488,2489,2490,2491,2492,2493,2494,2495,2496,2497,2498,2500,2502,2503,2504,2506,2507,2508,2509,2511,2512,2513,2514,2515,2517,2518,2523,2529,2532,2564,2566,2568,2574,2578,2585,2593,2597,2630,2638,2642,2649,2658) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND pp_child.pool_id IS NULL AND pp_mother.pool_id IS NULL;
COMMIT;

